{"lesson": "The channel is main total_changes plus other total_changes, the put operation is INSERT OR REPLACE, and no trigger is present. The simulator tracks per-connection total_changes cumulatively (including rolled-back work), models each connection's transaction as a private copy of committed state, and counts REPLACE as one direct change per put. Committed state is read from the committed dict only, so open transactions are invisible to the reader.", "scope": "The source uses INSERT OR REPLACE for put, no trigger, and channel = main total_changes + other total_changes. The model predicts channel, committed_count, and committed_sum for any action sequence within the disclosed family, preserving uncertainty when multiple family members remain consistent with the calibration receipts.", "source": "def investigate(context, acquire):
    history = acquire("history")

    def simulate(actions, put_op, trigger, channel_type):
        committed = {}
        main_pending = None
        other_pending = None
        main_total = 0
        other_total = 0
        main_last_changes = 0
        other_last_changes = 0

        def apply_put(conn, key, value):
            nonlocal main_pending, other_pending, main_total, other_total, main_last_changes, other_last_changes
            if conn == 'main':
                pending = main_pending
                total = main_total
            else:
                pending = other_pending
                total = other_total
            if pending is None:
                table = committed
            else:
                table = pending
            exists = key in table
            if put_op == 'ignore':
                if exists:
                    changes = 0
                else:
                    table[key] = value
                    changes = 1
            elif put_op == 'replace':
                table[key] = value
                changes = 1
            else:
                table[key] = value
                changes = 1
            total += changes
            insert_occurred = False
            if put_op == 'ignore':
                if not exists:
                    insert_occurred = True
            elif put_op == 'replace':
                insert_occurred = True
            else:
                if not exists:
                    insert_occurred = True
            if trigger and insert_occurred:
                total += 1
            if conn == 'main':
                main_pending = pending
                main_total = total
                main_last_changes = changes
            else:
                other_pending = pending
                other_total = total
                other_last_changes = changes

        def apply_update(conn, key, value):
            nonlocal main_pending, other_pending, main_total, other_total, main_last_changes, other_last_changes
            if conn == 'main':
                pending = main_pending
                total = main_total
            else:
                pending = other_pending
                total = other_total
            if pending is None:
                table = committed
            else:
                table = pending
            if key in table:
                table[key] = value
                changes = 1
            else:
                changes = 0
            total += changes
            if conn == 'main':
                main_pending = pending
                main_total = total
                main_last_changes = changes
            else:
                other_pending = pending
                other_total = total
                other_last_changes = changes

        def apply_delete(conn, key):
            nonlocal main_pending, other_pending, main_total, other_total, main_last_changes, other_last_changes
            if conn == 'main':
                pending = main_pending
                total = main_total
            else:
                pending = other_pending
                total = other_total
            if pending is None:
                table = committed
            else:
                table = pending
            if key in table:
                del table[key]
                changes = 1
            else:
                changes = 0
            total += changes
            if conn == 'main':
                main_pending = pending
                main_total = total
                main_last_changes = changes
            else:
                other_pending = pending
                other_total = total
                other_last_changes = changes

        def apply_begin(conn):
            nonlocal main_pending, other_pending
            if conn == 'main':
                if main_pending is None:
                    main_pending = dict(committed)
            else:
                if other_pending is None:
                    other_pending = dict(committed)

        def apply_commit(conn):
            nonlocal main_pending, other_pending, committed
            if conn == 'main':
                if main_pending is not None:
                    committed = main_pending
                    main_pending = None
            else:
                if other_pending is not None:
                    committed = other_pending
                    other_pending = None

        def apply_rollback(conn):
            nonlocal main_pending, other_pending
            if conn == 'main':
                main_pending = None
            else:
                other_pending = None

        for action in actions:
            op = action.get('op')
            conn = action.get('connection', 'main')
            if op == 'put':
                apply_put(conn, action['key'], action['value'])
            elif op == 'update':
                apply_update(conn, action['key'], action['value'])
            elif op == 'delete':
                apply_delete(conn, action['key'])
            elif op == 'begin':
                apply_begin(conn)
            elif op == 'commit':
                apply_commit(conn)
            elif op == 'rollback':
                apply_rollback(conn)

        committed_count = len(committed)
        committed_sum = sum(committed.values())
        if channel_type == 'changes':
            channel_value = main_last_changes
        elif channel_type == 'total_main':
            channel_value = main_total
        else:
            channel_value = main_total + other_total
        return channel_value, committed_count, committed_sum

    put_ops = ['ignore', 'replace', 'upsert']
    triggers = [False, True]
    channel_types = ['changes', 'total_main', 'total_both']

    valid_combos = []
    for put_op in put_ops:
        for trigger in triggers:
            for channel_type in channel_types:
                ok = True
                for receipt in history:
                    ch, cc, cs = simulate(receipt['actions'], put_op, trigger, channel_type)
                    obs = receipt['observed']
                    if ch != obs['channel'] or cc != obs['committed_count'] or cs != obs['committed_sum']:
                        ok = False
                        break
                if ok:
                    valid_combos.append((put_op, trigger, channel_type))

    if not valid_combos:
        return {"value": None, "unresolved": True}

    query_actions = context['actions']
    goal = context['goal']
    predictions = set()
    for put_op, trigger, channel_type in valid_combos:
        ch, cc, cs = simulate(query_actions, put_op, trigger, channel_type)
        if goal == 'channel':
            predictions.add(ch)
        elif goal == 'committed_count':
            predictions.add(cc)
        elif goal == 'committed_sum':
            predictions.add(cs)
        else:
            return {"value": None, "unresolved": True}

    if len(predictions) == 1:
        return {"value": predictions.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
"}
